import{_ as o,c as t,o as a,ae as i}from"./chunks/framework.Bi6zybwU.js";const h=JSON.parse('{"title":"Shortcode / Computed Value or HTML in WP Post / Woocommerce Table","description":"Shortcode / Computed Value or HTML in WP Post / Woocommerce Table","frontmatter":{"title":"Shortcode / Computed Value or HTML in WP Post / Woocommerce Table","description":"Shortcode / Computed Value or HTML in WP Post / Woocommerce Table"},"headers":[],"relativePath":"guide/wordpress-integration/shortcode-computed-value-or-html-in-wp-post-woocommerce-table.md","filePath":"guide/wordpress-integration/shortcode-computed-value-or-html-in-wp-post-woocommerce-table.md"}'),r={name:"guide/wordpress-integration/shortcode-computed-value-or-html-in-wp-post-woocommerce-table.md"};function l(s,e,n,c,d,u){return a(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="shortcode-computed-value-or-html-in-wp-post-woocommerce-table" tabindex="-1">Shortcode / Computed Value or HTML in WP Post / Woocommerce Table <a class="header-anchor" href="#shortcode-computed-value-or-html-in-wp-post-woocommerce-table" aria-label="Permalink to &quot;Shortcode / Computed Value or HTML in WP Post / Woocommerce Table&quot;">​</a></h1><p>For particular purposes, WordPress enables the use of a few default shortcodes. These shortcodes can be used on your table with the help of Ninja tables. Let&#39;s dive into this demonstration to learn about the application of this feature. We&#39;ve used the WP Posts table option for the demonstration.</p><ul><li>First, you need to make a WP Posts table using the Ninja Tables. So navigate to the plugin’s <strong>dashboard</strong> and click the <strong>WP Posts</strong> option.</li><li>Tap the Next button, and you&#39;ll find options to configure selected field properties.</li><li>Next, switch the required properties to the **Selected Properties **by checking &amp; clicking the right icon.</li><li>A table will be created automatically after you click the <strong>Save</strong> button. <img src="https://ninjatables.com/wp-content/uploads/2022/09/Shortcode-Table-1-scaled.webp" alt=""></li><li>Create a new column by clicking on the <strong>Add Column</strong> at the top of the table to use the Shortcodes / Computed Value in Ninja Tables. <img src="https://ninjatables.com/wp-content/uploads/2022/09/Shortcode-Table-2-scaled.webp" alt=""></li><li>Now, go to Dynamic Data Settings and click Field Type. There will be a drop-down option. From there, click on the Shortcode / Computed Value or HTML. <img src="https://ninjatables.com/wp-content/uploads/2022/09/Shortcode-Table-3-scaled.webp" alt="Shortcode / Computed Value or HTML"></li><li>By clicking the Shortcode / Computed Value or HTML option, you must use a shortcode to fill in the field input value field. <img src="https://ninjatables.com/wp-content/uploads/2022/09/Shortcode-Table-4-scaled.webp" alt=""></li><li>Follow the instructions given under Field Value until entering the value. Then, place the shortcode needed in the input fields. You can get the pre-built shortcodes from the docs.woocommerce.com website, or you can get those pre-defined shortcodes from various sources that are allowed in WordPress.</li><li>The shortcode is given in the Field Value input field to add to the cart.</li><li>Now, you will see a new column titled <strong>Buy Now</strong>, with its value generated in the admin section. <img src="https://ninjatables.com/wp-content/uploads/2023/01/shortcode-computed-value-9.webp" alt="new column with shortcode"></li><li>Then, tap on the Preview button to display the interface&#39;s final output. <img src="https://ninjatables.com/wp-content/uploads/2023/09/preview-table-after-creating-a-column-from-acf.jpg" alt="add to cart button with shortcode"> This is how you can use <strong>Shortcode / Computed Value or HTML</strong> in the WP Posts or WooCommerce option of Ninja Tables.</li></ul>',3)])])}const m=o(r,[["render",l]]);export{h as __pageData,m as default};
